#include "RecipeValidator.h"
#include "CraftingRecipeAsset.h"
#include "InventoryCore/InventoryComponent.h"
#include "InventoryCore/InventoryItem.h"
#include "CombiningAreaComponent.h"
URecipeValidator::URecipeValidator(){PrimaryComponentTick.bCanEverTick=false;}
bool URecipeValidator::CheckConditions(const UCraftingRecipeAsset*R)const{if(!R)return false;/* World condition providers must be attached by the game. */return true;}
bool URecipeValidator::HasRequiredTools(const UCraftingRecipeAsset*R,UInventoryComponent*Inv)const{if(!R||!Inv)return false;for(const auto&I:R->Ingredients)if(I.bIsTool&&!Inv->HasItem(I.ItemID,1))return false;return true;}
TArray<FName>URecipeValidator::GetMissingItems(UCraftingRecipeAsset*R,UInventoryComponent*Inv)const{TArray<FName>O;if(!R||!Inv)return O;TMap<FName,int32>Required;for(const auto&I:R->Ingredients)Required.FindOrAdd(I.ItemID)+=I.Count;for(const auto&Pair:Required)if(!Inv->HasItem(Pair.Key,Pair.Value))O.Add(Pair.Key);return O;}
bool URecipeValidator::AreaMatches(const UCraftingRecipeAsset*R,const UCombiningAreaComponent*A)const{if(!R||!A)return false;if(A->IsEmpty())return true;TMap<FName,int32>Required,Provided;for(const auto&Req:R->Ingredients)if(!Req.bIsTool)Required.FindOrAdd(Req.ItemID)+=Req.Count;for(const auto&Have:A->GetIngredients())Provided.FindOrAdd(Have.ItemID)+=Have.Count;for(const auto&Pair:Required)if(Provided.FindRef(Pair.Key)<Pair.Value)return false;return true;}
bool URecipeValidator::CanCraft(UCraftingRecipeAsset*R,UInventoryComponent*Inv)const{return R&&Inv&&CheckConditions(R)&&HasRequiredTools(R,Inv)&&GetMissingItems(R,Inv).IsEmpty()&&Inv->CanAddItem(R->Output.ItemID,R->Output.Count);}
FCraftingResult URecipeValidator::ValidateCraft(UCraftingRecipeAsset*R,UInventoryComponent*Inv,UCombiningAreaComponent*A)const{FCraftingResult Out;if(!R||!Inv){Out.Result=EInventoryResult::InvalidRequest;Out.ErrorMessage=FText::FromString(TEXT("Geçersiz tarif veya envanter"));return Out;}FString Err;if(!R->ValidateRecipe(Err)){Out.Result=EInventoryResult::NoRecipeMatch;Out.ErrorMessage=FText::FromString(Err);return Out;}if(!CheckConditions(R)){Out.Result=EInventoryResult::NoRecipeMatch;Out.ErrorMessage=FText::FromString(TEXT("Ortam koşulları uygun değil"));return Out;}if(!HasRequiredTools(R,Inv)){Out.Result=EInventoryResult::MissingTool;Out.ErrorMessage=FText::FromString(TEXT("Gerekli alet envanterde yok"));return Out;}if(!AreaMatches(R,A)){Out.Result=EInventoryResult::NotEnoughItems;Out.ErrorMessage=FText::FromString(TEXT("Birleştirme alanındaki malzemeler tarifle uyuşmuyor"));return Out;}const auto Missing=GetMissingItems(R,Inv);if(!Missing.IsEmpty()){Out.Result=EInventoryResult::NotEnoughItems;Out.ErrorMessage=FText::FromString(TEXT("Yetersiz malzeme"));return Out;}if(!Inv->CanAddItem(R->Output.ItemID,R->Output.Count)){Out.Result=EInventoryResult::InventoryFull;Out.ErrorMessage=FText::FromString(TEXT("Sonuç envanter kapasitesine sığmıyor"));return Out;}Out.Result=EInventoryResult::Success;Out.OutputItemID=R->Output.ItemID;Out.OutputCount=R->Output.Count;return Out;}
